// Miguel, 19 Nov 2026 17:4x UTC: "i will not accept any hardcoded geometry moving forwards. textures should be generated by chatgpt."
// Every plugin declares its geometry in manifest.json. Hand-made ("legacy") plugins may only disappear from the list below,
// never be added: a new plugin must be a story-prop (authored model), an effect (no scene geometry) or texture-driven.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const manifest = JSON.parse(fs.readFileSync(path.join(here, 'manifest.json'), 'utf8'));
// Ratchet: shrink this list as plugins move to generated textures. Never add to it.
const LEGACY_ALLOWED = ['pinpin-home', 'elder-sanctuary', 'timber-clearing', 'woodland-life', 'fluke', 'ship', 'manta', 'fish'];
const KINDS = ['story-prop', 'texture', 'effect', 'legacy'];

test('every plugin declares its geometry kind', () => {
  for (const p of manifest.plugins) assert.ok(KINDS.includes(p.geometry), `${p.name}: geometry must be one of ${KINDS.join(', ')}`);
});

test('no plugin outside the shrinking legacy list builds hand-made geometry', () => {
  const legacy = manifest.plugins.filter((p) => p.geometry === 'legacy').map((p) => p.name);
  for (const name of legacy) assert.ok(LEGACY_ALLOWED.includes(name), `${name} is hand-made geometry and not grandfathered; make it texture-driven`);
});

test('texture-driven plugins name generated inputs that exist with provenance', () => {
  for (const p of manifest.plugins.filter((q) => q.geometry === 'texture')) {
    assert.ok(Array.isArray(p.inputs) && p.inputs.length, `${p.name}: texture plugin must list its inputs`);
    for (const key of p.inputs) {
      const asset = manifest.assets?.[key];
      assert.ok(asset?.url, `${p.name}: input ${key} must be a manifest asset with a url`);
      assert.ok(fs.existsSync(path.join(here, '..', asset.url)), `${p.name}: ${asset.url} must be committed`);
      assert.ok(asset.provenance && fs.existsSync(path.join(here, '..', asset.provenance)), `${p.name}: ${key} needs a committed provenance file (prompt, model, date)`);
    }
  }
});
